UPDATE tdm54_chck_insuff
   SET tdm54_reg_date            = CAST(#{req.regDate} AS date)
     , tdm54_due_date            = CAST(#{req.dueDate} AS date)
     , tdm54_plan_action_emp_id  = #{req.planActionEmpId}
     , tdm54_action_nm           = #{req.actionName}
     , tdm54_action_plan         = #{req.actionPlan}
     , tdm54_upd_nm              = #{updName}
     , tdm54_upd_date            = f_sysdate()
 WHERE tdm54_chck_insuff_id      = #{req.chckInsuffId}
   AND tdm54_company_id          = #{companyId}

mapper.select:
SELECT FROM ( SELECT tdm54_chck_insuff.* , tdm54_occ_ym AS tdm54_check_ym /*발생년월*/ , tdm20_role_nm AS tdm54_role_nm /*직책명*/ , f_org_nm(tdm54_org_id, f_today()) AS tdm54_org_nm /*부서명*/ , f_emp_kor_nm(tdm54_plan_action_emp_id) AS tdm54_plan_action_emp_nm /*조치예정자*/ , f_emp_kor_nm(tdm54_plan_reg_emp_id) AS tdm54_plan_reg_emp_nm /*조치계획등록자*/ , f_emp_kor_nm(tdm54_action_emp_id) AS tdm54_action_emp_nm /*조치자*/ , CASE WHEN tdm54_occ_ym = TO_CHAR(f_today(),'YYYY.MM') THEN '10' WHEN tdm54_status_cd IN ('19','20','21','25','26') THEN tdm54_status_cd ELSE '11' END AS curr_status_cd FROM tdm54_chck_insuff INNER JOIN tdm20_role ON tdm20_role_id = tdm54_role_id
, ( SELECT f_get_tdmOrg_id2(CAST(#{companyId} AS numeric), CAST(#{orgId} AS numeric), CAST(#{endDate} AS date)) tdmorg_id ) o
WHERE tdm54_company_id = #{companyId}
AND tdm54_role_id = #{roleId}
AND ( tdm54_org_id IN (#{orgId}, tdmorg_id) OR #{orgId} IN ( SELECT tdm61_appr_org_id FROM tdm61_chck_insuff_appr WHERE tdm61_chck_insuff_id = tdm54_chck_insuff_id UNION ALL SELECT tdm60_appr_org_id FROM tdm60_chck_manl_appr WHERE tdm60_chck_manl_id = tdm54_chck_manl_id ) )
) t WHERE 1=1 AND COALESCE(curr_status_cd,'10') LIKE #{statusCode}
AND COALESCE(curr_status_cd,'10') IN ('10','11','26') /*(10:발생/11:조치중/26:승인반려)*/
AND tdm54_check_ym BETWEEN TO_CHAR(CAST(#{startDate} AS date),'YYYY.MM') AND TO_CHAR(CAST(#{endDate} AS date),'YYYY.MM')
ORDER BY tdm54_check_ym, tdm54_due_date, tdm54_chck_manl_id

SELECT COUNT(*)
  FROM tdm61_chck_insuff_appr
 WHERE tdm61_chck_insuff_id = #{chckInsuffId}

