     , tdm54_action_date   = CAST(#{actionDate} AS date)
     , tdm54_action_emp_id = #{actionEmpId}
     , tdm54_action_cmnt   = #{actionCmnt}
     , tdm54_upd_nm        = #{updName}
     , tdm54_upd_date      = f_sysdate()
