   SET tdm63_reg_date = CAST(#{row.regDate} AS date)
     , tdm63_content  = #{row.content}
     , tdm63_note     = #{row.note}
     , tdm63_upd_nm   = #{updName}
     , tdm63_upd_date = f_sysdate()
 WHERE tdm63_chck_insuff_record_id = #{row.chckInsuffRecordId}
   AND tdm63_chck_insuff_id        = #{chckInsuffId}

